# The shared traits say "The creature". Put the name of each monster in its place.
for _m in MON:
    _m.traits = [(n, t.replace("The creature", "The " + _m.ref()).replace("its allies", f"the {_m.ref()}'s allies"))
                 for n, t in _m.traits]
